-- BETWEEN CLASSES: ONE-TIME MANUAL SEED
-- Run in Supabase -> SQL Editor AFTER running schema.sql once.
-- This never deletes or overwrites existing schedule blocks.
-- To avoid duplicate/partial timetables it seeds only a completely empty account.
-- Replace the email below with your Supabase Authentication -> Users email.
-- Do not put passwords or service-role keys in this script.
DO $seed_planner$
DECLARE
  target_email text := 'REPLACE_WITH_YOUR_LOGIN_EMAIL';
  target_id uuid;
  existing_count integer;
BEGIN
  SELECT id INTO target_id
    FROM auth.users
    WHERE lower(email) = lower(target_email)
    FOR UPDATE;
  IF target_id IS NULL THEN
    RAISE EXCEPTION 'No Supabase Auth user found for email %', target_email;
  END IF;
  SELECT count(*) INTO existing_count FROM public.planner_blocks WHERE user_id = target_id;
  IF existing_count > 0 THEN
    RAISE NOTICE 'Skipped: % existing blocks for %. Nothing was changed.', existing_count, target_email;
    RETURN;
  END IF;

  INSERT INTO public.planner_blocks (user_id, day, start_time, end_time, title, category)
  SELECT target_id, b.day, b.start_time::time, b.end_time::time, b.title, b.category
  FROM jsonb_to_recordset($blocks$[{"day":0,"start_time":"09:15","end_time":"10:45","title":"Digital Design","category":"class"},{"day":0,"start_time":"11:00","end_time":"12:30","title":"Calculus","category":"class"},{"day":0,"start_time":"14:00","end_time":"15:30","title":"Linear Algebra","category":"class"},{"day":1,"start_time":"09:15","end_time":"10:45","title":"C Programming","category":"class"},{"day":1,"start_time":"11:00","end_time":"12:30","title":"Economics","category":"class"},{"day":1,"start_time":"14:00","end_time":"15:30","title":"Calculus","category":"class"},{"day":1,"start_time":"15:45","end_time":"17:15","title":"Physical Education","category":"class"},{"day":2,"start_time":"09:15","end_time":"10:45","title":"Digital Design","category":"class"},{"day":2,"start_time":"14:00","end_time":"15:30","title":"Linear Algebra","category":"class"},{"day":2,"start_time":"16:30","end_time":"18:00","title":"Linear Algebra Tutorial","category":"class"},{"day":3,"start_time":"14:00","end_time":"15:30","title":"Python Programming","category":"class"},{"day":3,"start_time":"15:45","end_time":"17:15","title":"Physical Education","category":"class"},{"day":4,"start_time":"11:00","end_time":"12:30","title":"Calculus Tutorial","category":"class"},{"day":4,"start_time":"14:00","end_time":"15:30","title":"Digital Design Tutorial","category":"class"},{"day":4,"start_time":"15:45","end_time":"17:15","title":"Physical Education","category":"class"},{"day":5,"start_time":"09:00","end_time":"10:30","title":"Physical Education (TT)","category":"class"},{"day":5,"start_time":"11:00","end_time":"12:30","title":"C Programming","category":"class"},{"day":5,"start_time":"14:00","end_time":"15:30","title":"Python Programming","category":"class"},{"day":0,"start_time":"16:30","end_time":"18:00","title":"Calculus / Linear Algebra review","category":"study"},{"day":0,"start_time":"18:00","end_time":"19:00","title":"Codeforces — practice","category":"hobby"},{"day":0,"start_time":"20:00","end_time":"21:00","title":"Digital Design self-study","category":"study"},{"day":0,"start_time":"21:00","end_time":"22:00","title":"Unsolved Monday — publish / coordinate","category":"pio"},{"day":1,"start_time":"18:00","end_time":"19:30","title":"Programming / assignments","category":"study"},{"day":1,"start_time":"20:30","end_time":"21:30","title":"Economics / Calculus review","category":"study"},{"day":2,"start_time":"11:00","end_time":"12:30","title":"Digital Design / pending work","category":"study"},{"day":2,"start_time":"19:00","end_time":"20:00","title":"Linear Algebra recap","category":"study"},{"day":2,"start_time":"20:00","end_time":"21:30","title":"Codeforces — practice","category":"hobby"},{"day":3,"start_time":"09:30","end_time":"11:00","title":"Deep work / assignments","category":"study"},{"day":3,"start_time":"11:00","end_time":"12:30","title":"Pioneers — research / production","category":"pio"},{"day":3,"start_time":"18:15","end_time":"19:15","title":"Python revision","category":"study"},{"day":3,"start_time":"20:15","end_time":"21:45","title":"Codeforces / try a new hobby","category":"hobby"},{"day":4,"start_time":"09:30","end_time":"10:30","title":"Tutorial prep","category":"study"},{"day":4,"start_time":"18:15","end_time":"19:45","title":"Assignments / revision","category":"study"},{"day":4,"start_time":"20:45","end_time":"21:45","title":"Pioneers — close submissions / review","category":"pio"},{"day":5,"start_time":"16:30","end_time":"18:00","title":"Weekly academic backlog","category":"study"},{"day":5,"start_time":"18:00","end_time":"19:00","title":"Pioneers — solution handoff","category":"pio"},{"day":5,"start_time":"20:00","end_time":"21:00","title":"Weekly revision","category":"study"},{"day":6,"start_time":"10:00","end_time":"11:30","title":"Focused academic catch-up","category":"study"},{"day":6,"start_time":"11:30","end_time":"13:00","title":"Pioneers — prepare / review","category":"pio"},{"day":6,"start_time":"14:30","end_time":"16:00","title":"Codeforces / new hobby","category":"hobby"},{"day":6,"start_time":"18:00","end_time":"19:00","title":"Upcoming-week academic prep","category":"study"},{"day":0,"start_time":"08:00","end_time":"09:00","title":"Breakfast and morning routine","category":"rest"},{"day":0,"start_time":"12:30","end_time":"14:00","title":"Lunch and downtime","category":"rest"},{"day":0,"start_time":"15:30","end_time":"16:30","title":"Rest / friends / snack","category":"rest"},{"day":0,"start_time":"19:00","end_time":"20:00","title":"Dinner and break","category":"rest"},{"day":0,"start_time":"22:00","end_time":"23:30","title":"Free time / winding down","category":"free"},{"day":1,"start_time":"08:00","end_time":"09:00","title":"Breakfast and morning routine","category":"rest"},{"day":1,"start_time":"12:30","end_time":"14:00","title":"Lunch and downtime","category":"rest"},{"day":1,"start_time":"17:15","end_time":"18:00","title":"Recovery and snack","category":"rest"},{"day":1,"start_time":"19:30","end_time":"20:30","title":"Dinner and break","category":"rest"},{"day":1,"start_time":"21:30","end_time":"23:30","title":"Friends / entertainment / free time","category":"free"},{"day":2,"start_time":"08:00","end_time":"09:00","title":"Breakfast and morning routine","category":"rest"},{"day":2,"start_time":"12:30","end_time":"14:00","title":"Lunch and downtime","category":"rest"},{"day":2,"start_time":"15:30","end_time":"16:30","title":"Rest and snack","category":"rest"},{"day":2,"start_time":"18:00","end_time":"19:00","title":"Dinner and recovery","category":"rest"},{"day":2,"start_time":"21:30","end_time":"23:30","title":"Free time","category":"free"},{"day":3,"start_time":"08:30","end_time":"09:30","title":"Breakfast and easy morning","category":"rest"},{"day":3,"start_time":"12:30","end_time":"14:00","title":"Lunch and downtime","category":"rest"},{"day":3,"start_time":"17:15","end_time":"18:15","title":"Rest and snack","category":"rest"},{"day":3,"start_time":"19:15","end_time":"20:15","title":"Dinner","category":"rest"},{"day":3,"start_time":"21:45","end_time":"23:30","title":"Free time","category":"free"},{"day":4,"start_time":"08:30","end_time":"09:30","title":"Breakfast and morning routine","category":"rest"},{"day":4,"start_time":"12:30","end_time":"14:00","title":"Lunch and downtime","category":"rest"},{"day":4,"start_time":"17:15","end_time":"18:15","title":"Recovery and break","category":"rest"},{"day":4,"start_time":"19:45","end_time":"20:45","title":"Dinner","category":"rest"},{"day":4,"start_time":"21:45","end_time":"23:30","title":"Social evening / free time","category":"free"},{"day":5,"start_time":"08:00","end_time":"08:45","title":"Breakfast and routine","category":"rest"},{"day":5,"start_time":"12:30","end_time":"14:00","title":"Lunch and downtime","category":"rest"},{"day":5,"start_time":"15:30","end_time":"16:30","title":"Rest and snack","category":"rest"},{"day":5,"start_time":"19:00","end_time":"20:00","title":"Dinner and break","category":"rest"},{"day":5,"start_time":"21:00","end_time":"23:30","title":"Friends / games / free time","category":"free"},{"day":6,"start_time":"09:00","end_time":"10:00","title":"Relaxed breakfast","category":"rest"},{"day":6,"start_time":"13:00","end_time":"14:30","title":"Lunch and downtime","category":"rest"},{"day":6,"start_time":"16:00","end_time":"18:00","title":"Unstructured free time / outing","category":"free"},{"day":6,"start_time":"19:00","end_time":"20:00","title":"Dinner","category":"rest"},{"day":6,"start_time":"20:00","end_time":"21:00","title":"Optional Pioneers prep / handoff","category":"pio"},{"day":6,"start_time":"21:00","end_time":"23:30","title":"Rest and friends","category":"free"}]$blocks$::jsonb)
    AS b(day smallint, start_time text, end_time text, title text, category text);

  -- Mark the existing automatic-initialization system as completed, when present,
  -- so older deployments won't reinitialize the user's schedule.
  IF to_regclass('public.planner_initializations') IS NOT NULL THEN
    INSERT INTO public.planner_initializations(user_id) VALUES (target_id)
      ON CONFLICT (user_id) DO NOTHING;
  END IF;
  RAISE NOTICE 'Seeded 77 editable blocks for %', target_email;
END;
$seed_planner$;
